PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?supplier a pv:Supplier ;
              pv:supplies prodi:Compensator .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?encoder a pv:Encoder ;
             pv:hasPrice ?price ;
             pv:suppliedBy ?supplier .
  ?supplier pv:country ?country .
  FILTER(?country = "France" || ?country = "Germany")
} ORDER BY ASC(?price) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (MAX(?price) AS ?maxPrice) WHERE {
  ?service a pv:Service ;
             pv:providedBy ?result ;
             pv:hasPrice ?price .
} GROUP BY ?result ORDER BY DESC(?maxPrice) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?supplier a pv:Supplier ;
              pv:supplies prodi:LCD ;
              pv:country "US" ;
              pv:city ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?service a pv:Service ;
             pv:appliesTo ?bom .
  ?bom a pv:BOM ;
       pv:hasPart ?part .
  ?part pv:sourcedFrom "Russia" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?country ?price WHERE {
  ?hardware a pv:Hardware ;
              pv:suppliedBy ?supplier ;
              pv:hasPrice ?price .
  ?supplier rdfs:label ?supplierName ;
            pv:locatedIn ?country .
} ORDER BY DESC(?price) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?lightestItem ?heaviestItem WHERE {
  ?item a pv:Hardware ;
          pv:hasCategory ?category ;
          pv:hasWeight ?weight .
  {
    SELECT ?category (MIN(?weight) AS ?minWeight) WHERE {
      ?item a pv:Hardware ;
              pv:hasCategory ?category ;
              pv:hasWeight ?weight .
    } GROUP BY ?category
  }
  {
    SELECT ?category (MAX(?weight) AS ?maxWeight) WHERE {
      ?item a pv:Hardware ;
              pv:hasCategory ?category ;
              pv:hasWeight ?weight .
    } GROUP BY ?category
  }
  FILTER(?weight = ?minWeight)
  BIND(?item AS ?lightestItem)
  FILTER(?weight = ?maxWeight)
  BIND(?item AS ?heaviestItem)
} GROUP BY ?category ?lightestItem ?heaviestItem

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?employee ?name ?email ?phone ?department ?directReport WHERE {
  ?employee a pv:Employee ;
              pv:name ?name ;
              pv:email ?email ;
              pv:phone ?phone ;
              pv:belongsToDepartment ?department .
  OPTIONAL { ?employee pv:hasDirectReport ?directReport . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (AVG(?unitCost) AS ?averageUnitCost) WHERE {
  ?bom a pv:BOM ;
       pv:hasPart ?part .
  ?part a pv:Hardware ;
        pv:hasUnitCost ?unitCost .
} GROUP BY ?bom ORDER BY DESC(?averageUnitCost) LIMIT 1
